 28	type RunCommand struct {
 29		*cmds.CommandDescription
 30	}
 31	
 32	type RunSettings struct {
 33		Config             string `glazed.parameter:"config"`
 34		Modes              string `glazed.parameter:"modes"`
 35		DryRun             bool   `glazed.parameter:"dry-run"`
 36		PixelDiffThreshold int    `glazed.parameter:"pixeldiff-threshold"`
 37	}
 38	
 39	func NewRunCommand() (*RunCommand, error) {
 40		glazedLayer, err := schema.NewGlazedSchema()
 41		if err != nil {
 42			return nil, err
 43		}
 44		commandSettingsLayer, err := cli.NewCommandSettingsLayer()
 45		if err != nil {
 46			return nil, err
 47		}
 48	
 49		cmdDesc := cmds.NewCommandDescription(
 50			"run",
 51			cmds.WithShort("Run sbcap capture and analysis modes"),
 52			cmds.WithLong("Run sbcap using a YAML capture plan and one or more modes."),
 53			cmds.WithFlags(
 54				fields.New(
 55					"config",
 56					fields.TypeString,
 57					fields.WithHelp("Path to sbcap YAML config"),
 58				),
 59				fields.New(
 60					"modes",
 61					fields.TypeString,
 62					fields.WithDefault(""),
 63					fields.WithHelp("Comma-delimited list of modes (capture,cssdiff,matched-styles,ai-review,full)"),
 64				),
 65				fields.New(
 66					"dry-run",
 67					fields.TypeBool,
 68					fields.WithDefault(false),
 69					fields.WithHelp("Validate config and modes without running browser actions"),
 70				),
 71				fields.New(
 72					"pixeldiff-threshold",
 73					fields.TypeInteger,
 74					fields.WithDefault(30),
 75					fields.WithHelp("Pixel diff threshold (0-255) used by pixeldiff mode"),
 76				),
 77			),
 78			cmds.WithLayersList(glazedLayer, commandSettingsLayer),
 79		)
 80	
 81		return &RunCommand{CommandDescription: cmdDesc}, nil
 82	}
 83	
 84	func (c *RunCommand) RunIntoGlazeProcessor(
 85		ctx context.Context,
 86		vals *values.Values,
 87		gp middlewares.Processor,
 88	) error {
 89		settings := &RunSettings{}
 90		if err := values.DecodeSectionInto(vals, schema.DefaultSlug, settings); err != nil {
 91			return err
 92		}
 93		if settings.Config == "" {
 94			return fmt.Errorf("--config is required")
 95		}
 96	
 97		cfg, err := config.Load(settings.Config)
 98		if err != nil {
 99			return err
100		}
101	
102		modesRaw := settings.Modes
103		if modesRaw == "" && len(cfg.Modes) > 0 {
104			modesRaw = joinModes(cfg.Modes)
105		}
106	
107		modesList, err := runner.NormalizeModes(modesRaw)
108		if err != nil {
109			return err
110		}
111	
112		result, err := runner.Run(ctx, cfg, modesList, settings.DryRun, runner.RunOptions{
113			PixelDiffThreshold: settings.PixelDiffThreshold,
114		})
115		if err != nil && settings.DryRun {
116			return err
117		}
118	
119		for _, r := range result.Results {
120			row := types.NewRow(
121				types.MRP("mode", r.Mode),
122				types.MRP("status", r.Status),
123				types.MRP("message", r.Message),
124			)
125			if err := gp.AddRow(ctx, row); err != nil {
126				return err
127			}
128		}
129	
130		if !settings.DryRun {
131			if containsMode(modesList, "capture") {
132				if err := emitCoverageRows(ctx, gp, cfg.Output.Dir); err != nil {
133					return err
134				}
135			}
136			if containsMode(modesList, "story-discovery") {
137				if err := emitStoryRows(ctx, gp, cfg.Output.Dir); err != nil {
138					return err
139				}
140			}
141		}
142	
143		return err
144	}
145	
146	func joinModes(modes []string) string {
147		out := ""
148		for i, m := range modes {
149			if i == 0 {
150				out = m
151				continue
152			}
153			out += "," + m
154		}
155		return out
156	}
157	
158	func containsMode(modesList []string, value string) bool {
159		for _, m := range modesList {
160			if m == value {
161				return true
162			}
163		}
164		return false
165	}
