187	func emitStoryRows(ctx context.Context, gp middlewares.Processor, outDir string) error {
188		data, err := os.ReadFile(filepath.Join(outDir, "stories.json"))
189		if err != nil {
190			return err
191		}
192		var stories modes.StoryDiscoveryResult
193		if err := json.Unmarshal(data, &stories); err != nil {
194			return err
