 57	func CSSDiff(ctx context.Context, cfg *config.Config) error {
 58		if !cfg.Output.WriteJSON && !cfg.Output.WriteMarkdown {
 59			return nil
 60		}
 61	
 62		if err := os.MkdirAll(cfg.Output.Dir, 0o755); err != nil {
 63			return err
 64		}
 65	
 66		browser, err := driver.NewBrowser(ctx)
 67		if err != nil {
 68			return err
 69		}
 70		defer browser.Close()
 71	
 72		originalPage, err := browser.NewPage()
 73		if err != nil {
 74			return err
 75		}
 76		defer originalPage.Close()
 77	
 78		reactPage, err := browser.NewPage()
 79		if err != nil {
 80			return err
 81		}
 82		defer reactPage.Close()
 83	
 84		if err := originalPage.SetViewport(cfg.Original.Viewport.Width, cfg.Original.Viewport.Height); err != nil {
 85			return err
 86		}
 87		if err := reactPage.SetViewport(cfg.React.Viewport.Width, cfg.React.Viewport.Height); err != nil {
 88			return err
 89		}
 90	
 91		if err := originalPage.Goto(cfg.Original.URL); err != nil {
 92			return err
 93		}
 94		if cfg.Original.WaitMS > 0 {
 95			originalPage.Wait(time.Duration(cfg.Original.WaitMS) * time.Millisecond)
 96		}
 97	
 98		if err := reactPage.Goto(cfg.React.URL); err != nil {
 99			return err
100		}
101		if cfg.React.WaitMS > 0 {
102			reactPage.Wait(time.Duration(cfg.React.WaitMS) * time.Millisecond)
103		}
104	
105		result := CSSDiffResult{}
106		for _, style := range cfg.Styles {
107			origSelector := selectorForTarget(style.Selector, style.SelectorOriginal)
108			reactSelector := selectorForTarget(style.Selector, style.SelectorReact)
109	
110			origSpec := style
111			origSpec.Selector = origSelector
112			reactSpec := style
113			reactSpec.Selector = reactSelector
114	
115			origSnap, err := evaluateStyle(originalPage, origSpec)
116			if err != nil {
117				return err
118			}
119			reactSnap, err := evaluateStyle(reactPage, reactSpec)
120			if err != nil {
121				return err
122			}
123			diffs := buildDiffs(style.Props, origSnap, reactSnap)
124			result.Styles = append(result.Styles, StyleResult{
125				Name:             style.Name,
126				Selector:         style.Selector,
127				OriginalSelector: origSelector,
128				ReactSelector:    reactSelector,
129				Original:         origSnap,
130				React:            reactSnap,
131				Diffs:            diffs,
132			})
133		}
134	
135		if cfg.Output.WriteJSON {
136			if err := writeJSON(filepath.Join(cfg.Output.Dir, "cssdiff.json"), result); err != nil {
137				return err
138			}
139		}
140		if cfg.Output.WriteMarkdown {
141			if err := writeCSSMarkdown(filepath.Join(cfg.Output.Dir, "cssdiff.md"), result); err != nil {
142				return err
143			}
144		}
145	
146		return nil
147	}
