149	func evaluateStyle(page *driver.Page, spec config.StyleSpec) (StyleSnapshot, error) {
150		propsJSON, _ := json.Marshal(spec.Props)
151		attrsJSON, _ := json.Marshal(spec.Attributes)
152		script := fmt.Sprintf(`(() => {
153		  const props = %s;
154		  const attrs = %s;
155		  const el = document.querySelector(%q);
156		  if (!el) return { exists: false, computed: {}, bounds: null, attributes: {} };
157		  const style = window.getComputedStyle(el);
158		  const computed = {};
159		  props.forEach((p) => {
160		    computed[p] = style.getPropertyValue(p) || style[p] || "";
161		  });
162		  let bounds = null;
163		  if (%t) {
164		    const rect = el.getBoundingClientRect();
165		    bounds = { x: rect.x, y: rect.y, width: rect.width, height: rect.height };
166		  }
167		  const attributes = {};
168		  attrs.forEach((a) => {
169		    attributes[a] = el.getAttribute(a);
170		  });
171		  return { exists: true, computed, bounds, attributes };
172		})()`, string(propsJSON), string(attrsJSON), spec.Selector, spec.IncludeBounds)
173	
174		out := styleEvalResult{}
175		if err := page.Evaluate(script, &out); err != nil {
176			return StyleSnapshot{}, err
177		}
178	
179		return StyleSnapshot{
180			Exists:     out.Exists,
181			Computed:   out.Computed,
182			Bounds:     out.Bounds,
183			Attributes: out.Attributes,
184		}, nil
185	}
186	
187	func buildDiffs(props []string, orig StyleSnapshot, react StyleSnapshot) []StyleDiff {
188		var diffs []StyleDiff
189		for _, prop := range props {
190			origVal := strings.TrimSpace(orig.Computed[prop])
191			reactVal := strings.TrimSpace(react.Computed[prop])
192			if origVal != reactVal {
193				diffs = append(diffs, StyleDiff{Property: prop, Original: origVal, React: reactVal})
194			}
195		}
196		return diffs
197	}
198	
199	func writeCSSMarkdown(path string, result CSSDiffResult) error {
200		content := "# sbcap CSS Diff Report\n\n"
201		for _, s := range result.Styles {
202			content += fmt.Sprintf("## %s\n\n", s.Name)
203			if s.OriginalSelector != "" && s.ReactSelector != "" && s.OriginalSelector != s.ReactSelector {
204				content += fmt.Sprintf("Selector (original): `%s`\n\n", s.OriginalSelector)
205				content += fmt.Sprintf("Selector (react): `%s`\n\n", s.ReactSelector)
206			} else if s.Selector != "" {
207				content += fmt.Sprintf("Selector: `%s`\n\n", s.Selector)
208			} else if s.OriginalSelector != "" {
209				content += fmt.Sprintf("Selector: `%s`\n\n", s.OriginalSelector)
210			}
211			if !s.Original.Exists && !s.React.Exists {
212				content += "Both original and react are missing this selector.\n\n"
213				continue
214			}
215			content += "| Property | Original | React |\n"
216			content += "| --- | --- | --- |\n"
217			for _, diff := range s.Diffs {
218				content += fmt.Sprintf("| %s | %s | %s |\n", diff.Property, diff.Original, diff.React)
219			}
220			content += "\n"
221		}
222		return os.WriteFile(path, []byte(content), 0o644)
223	}
