200		content := "# css-visual-diff CSS Diff Report\n\n"
201		for _, s := range result.Styles {
202			content += fmt.Sprintf("## %s\n\n", s.Name)
203			if s.OriginalSelector != "" && s.ReactSelector != "" && s.OriginalSelector != s.ReactSelector {
204				content += fmt.Sprintf("Selector (original): `%s`\n\n", s.OriginalSelector)
205				content += fmt.Sprintf("Selector (react): `%s`\n\n", s.ReactSelector)
206			} else if s.Selector != "" {
207				content += fmt.Sprintf("Selector: `%s`\n\n", s.Selector)
208			} else if s.OriginalSelector != "" {
209				content += fmt.Sprintf("Selector: `%s`\n\n", s.OriginalSelector)
210			}
211			if !s.Original.Exists && !s.React.Exists {
212				content += "Both original and react are missing this selector.\n\n"
213				continue
214			}
215			content += "| Property | Original | React |\n"
216			content += "| --- | --- | --- |\n"
217			for _, diff := range s.Diffs {
218				content += fmt.Sprintf("| %s | %s | %s |\n", diff.Property, diff.Original, diff.React)
219			}
220			content += "\n"
221		}
222		return os.WriteFile(path, []byte(content), 0o644)
223	}
