308	func buildWinnerDiffs(props []string, orig MatchedSnapshot, react MatchedSnapshot) []WinnerDiff {
309		var diffs []WinnerDiff
310		origCandidates := collectCandidates(orig.Rules)
311		reactCandidates := collectCandidates(react.Rules)
312		for _, prop := range props {
313			origWinner := selectWinner(origCandidates[prop])
314			reactWinner := selectWinner(reactCandidates[prop])
315			diffs = append(diffs, WinnerDiff{Property: prop, Original: origWinner, React: reactWinner})
316		}
317		return diffs
318	}
319	
320	func collectCandidates(rules []MatchedRule) map[string][]Candidate {
321		candidates := map[string][]Candidate{}
322		order := 0
323		for _, rule := range rules {
324			for _, prop := range rule.Properties {
325				order++
326				candidate := Candidate{
327					Property:    prop.Name,
328					Value:       prop.Value,
329					Selector:    rule.Selector,
330					Important:   prop.Important,
331					Specificity: rule.Specificity,
332					Origin:      rule.Origin,
333					Order:       order,
334				}
335				candidates[prop.Name] = append(candidates[prop.Name], candidate)
336			}
337		}
338		return candidates
339	}
340	
341	func selectWinner(candidates []Candidate) Winner {
342		if len(candidates) == 0 {
343			return Winner{}
344		}
345		winner := candidates[0]
346		for i := 1; i < len(candidates); i++ {
347			if candidateBeats(candidates[i], winner) {
348				winner = candidates[i]
349			}
350		}
351		return Winner{
352			Selector:    winner.Selector,
353			Value:       winner.Value,
354			Important:   winner.Important,
355			Origin:      winner.Origin,
356			Specificity: winner.Specificity,
357		}
358	}
359	
360	func candidateBeats(a Candidate, b Candidate) bool {
361		if a.Important != b.Important {
362			return a.Important && !b.Important
363		}
364		if originPriority(a.Origin) != originPriority(b.Origin) {
365			return originPriority(a.Origin) > originPriority(b.Origin)
366		}
367		if cmp := a.Specificity.Compare(b.Specificity); cmp != 0 {
368			return cmp > 0
369		}
370		return a.Order > b.Order
371	}
372	
373	func originPriority(origin CascadeOrigin) int {
374		switch origin {
375		case OriginInline:
376			return 3
377		case OriginAuthor:
378			return 2
379		case OriginUserAgent:
380			return 1
381		default:
382			return 2
383		}
384	}
