386	func boxModelBounds(model *dom.BoxModel) *Bounds {
387		if model == nil || len(model.Content) < 8 {
388			return nil
389		}
390		content := model.Content
391		return &Bounds{
392			X:      content[0],
393			Y:      content[1],
394			Width:  content[2] - content[0],
