399	func writeMatchedMarkdown(path string, result MatchedStylesResult) error {
400		content := "# css-visual-diff Matched Styles Report\n\n"
401		content += "Winners are resolved using CSS cascade rules: `!important` first, then origin (inline > author > user-agent), then selector specificity, then source order.\n\n"
402		for _, s := range result.Styles {
403			content += fmt.Sprintf("## %s\n\n", s.Name)
404			if s.OriginalSelector != "" && s.ReactSelector != "" && s.OriginalSelector != s.ReactSelector {
405				content += fmt.Sprintf("Selector (original): `%s`\n\n", s.OriginalSelector)
406				content += fmt.Sprintf("Selector (react): `%s`\n\n", s.ReactSelector)
407			} else if s.Selector != "" {
408				content += fmt.Sprintf("Selector: `%s`\n\n", s.Selector)
409			} else if s.OriginalSelector != "" {
410				content += fmt.Sprintf("Selector: `%s`\n\n", s.OriginalSelector)
411			}
412			content += "### Winner Summary\n\n"
413			content += "| Property | Original Winner | React Winner |\n"
414			content += "| --- | --- | --- |\n"
415			for _, w := range s.Winners {
416				content += fmt.Sprintf("| %s | %s | %s |\n", w.Property, formatWinner(w.Original), formatWinner(w.React))
417			}
418			content += "\n"
419		}
420		return os.WriteFile(path, []byte(content), 0o644)
421	}
