423	func hasReport(reports []string, value string) bool {
424		for _, r := range reports {
425			if r == value {
426				return true
427			}
428		}
429		return false
430	}
431	
432	func selectorFromRuleMatch(ruleMatch *css.RuleMatch) (string, Specificity) {
433		if ruleMatch == nil || ruleMatch.Rule == nil || ruleMatch.Rule.SelectorList == nil {
434			return "", Specificity{}
435		}
436		selectors := ruleMatch.Rule.SelectorList.Selectors
437		if len(ruleMatch.MatchingSelectors) > 0 && len(selectors) > 0 {
438			var bestSelector *css.Value
439			bestSpecificity := Specificity{}
440			hasBest := false
441			for _, idx := range ruleMatch.MatchingSelectors {
442				if idx < 0 || int(idx) >= len(selectors) {
443					continue
444				}
445				value := selectors[idx]
446				spec := specificityFromValue(value)
447				if !hasBest || spec.Compare(bestSpecificity) > 0 {
448					bestSelector = value
449					bestSpecificity = spec
450					hasBest = true
451				}
452			}
453			if bestSelector != nil {
454				return bestSelector.Text, bestSpecificity
455			}
456		}
457		if len(selectors) > 0 {
458			return selectors[0].Text, specificityFromValue(selectors[0])
459		}
460		text := ruleMatch.Rule.SelectorList.Text
461		return text, specificityForSelectorList(text)
462	}
463	
464	func specificityFromValue(value *css.Value) Specificity {
465		if value == nil {
466			return Specificity{}
467		}
468		if value.Specificity != nil {
469			return Specificity{
470				A: int(value.Specificity.A),
471				B: int(value.Specificity.B),
472				C: int(value.Specificity.C),
473			}
474		}
475		return computeSpecificity(value.Text)
476	}
477	
478	func originFromRule(ruleMatch *css.RuleMatch) CascadeOrigin {
479		if ruleMatch == nil || ruleMatch.Rule == nil {
480			return OriginAuthor
481		}
482		switch ruleMatch.Rule.Origin {
483		case css.StyleSheetOriginUserAgent:
484			return OriginUserAgent
485		case css.StyleSheetOriginRegular, css.StyleSheetOriginInjected, css.StyleSheetOriginInspector:
486			return OriginAuthor
487		default:
488			return OriginAuthor
489		}
490	}
491	
492	func formatWinner(winner Winner) string {
493		if strings.TrimSpace(winner.Selector) == "" && strings.TrimSpace(winner.Value) == "" {
494			return "none"
495		}
496		important := ""
497		if winner.Important {
498			important = " !important"
499		}
500		return fmt.Sprintf("%s (%s%s; origin=%s; spec=%s)", winner.Selector, winner.Value, important, winner.Origin, winner.Specificity.String())
501	}
502	
503	func specificityForSelectorList(selectorList string) Specificity {
504		selectors := splitSelectorList(selectorList)
505		best := Specificity{}
506		hasBest := false
507		for _, sel := range selectors {
508			trimmed := strings.TrimSpace(sel)
509			if trimmed == "" {
510				continue
511			}
512			spec := computeSpecificity(trimmed)
513			if !hasBest || spec.Compare(best) > 0 {
514				best = spec
515				hasBest = true
516			}
517		}
518		if !hasBest {
519			return Specificity{}
520		}

