 16	// FactoryBuilder composes explicit module and runtime initializer configuration
 17	// before producing an immutable Factory.
 18	type FactoryBuilder struct {
 19		settings builderSettings
 20	
 21		modules                 []ModuleSpec
 22		runtimeModuleRegistrars []RuntimeModuleRegistrar
 23		runtimeInitializers     []RuntimeInitializer
 24		built                   bool
 25	}
 26	
 27	// Factory creates runtime instances from an immutable build plan.
 28	type Factory struct {
 29		settings                builderSettings
 30		modules                 []ModuleSpec
 31		runtimeModuleRegistrars []RuntimeModuleRegistrar
 32		runtimeInitializers     []RuntimeInitializer
 33	}
 34	
 35	// NewBuilder starts a new explicit runtime composition flow.
 36	func NewBuilder(opts ...Option) *FactoryBuilder {
 37		settings := defaultBuilderSettings()
 38		for _, opt := range opts {
 39			if opt != nil {
 40				opt(&settings)
 41			}
 42		}
 43		return &FactoryBuilder{
 44			settings: settings,
 45		}
 46	}
 47	
 48	func (b *FactoryBuilder) assertMutable() {
 49		if b == nil {
 50			panic("engine builder is nil")
 51		}
 52		if b.built {
 53			panic("engine builder is already built and immutable")
 54		}
 55	}
 56	
 57	// WithRequireOptions appends require options to the current builder.
 58	func (b *FactoryBuilder) WithRequireOptions(opts ...require.Option) *FactoryBuilder {
 59		b.assertMutable()
 60		b.settings.requireOptions = append(b.settings.requireOptions, opts...)
 61		return b
 62	}
 63	
 64	// WithModules appends static module registrations.
 65	func (b *FactoryBuilder) WithModules(mods ...ModuleSpec) *FactoryBuilder {
 66		b.assertMutable()
 67		b.modules = append(b.modules, mods...)
 68		return b
 69	}
 70	
 71	// WithRuntimeModuleRegistrars appends runtime-scoped module registration hooks.
 72	func (b *FactoryBuilder) WithRuntimeModuleRegistrars(registrars ...RuntimeModuleRegistrar) *FactoryBuilder {
 73		b.assertMutable()
 74		b.runtimeModuleRegistrars = append(b.runtimeModuleRegistrars, registrars...)
 75		return b
 76	}
 77	
 78	// WithRuntimeInitializers appends runtime initialization hooks executed for
 79	// each created runtime instance.
 80	func (b *FactoryBuilder) WithRuntimeInitializers(inits ...RuntimeInitializer) *FactoryBuilder {
 81		b.assertMutable()
 82		b.runtimeInitializers = append(b.runtimeInitializers, inits...)
 83		return b
 84	}
 85	
 86	func validateUniqueIDs[T interface{ ID() string }](entries []T, kind string) error {
 87		seen := map[string]int{}
 88		for i, entry := range entries {
 89			id := strings.TrimSpace(entry.ID())
 90			if id == "" {
 91				return fmt.Errorf("%s at index %d has empty ID", kind, i)
 92			}
 93			if j, ok := seen[id]; ok {
 94				return fmt.Errorf("duplicate %s ID %q at indexes %d and %d", kind, id, j, i)
 95			}
 96			seen[id] = i
 97		}
 98		return nil
 99	}
100	
101	// Build validates and freezes the composition into an immutable Factory.
102	func (b *FactoryBuilder) Build() (*Factory, error) {
103		if b == nil {
104			return nil, fmt.Errorf("engine builder is nil")
105		}
106		b.assertMutable()
107	
108		modules_ := make([]ModuleSpec, 0, len(b.modules))
109		for i, mod := range b.modules {
110			if mod == nil {
111				return nil, fmt.Errorf("module spec at index %d is nil", i)
112			}
113			modules_ = append(modules_, mod)
114		}
115		runtimeRegistrars := make([]RuntimeModuleRegistrar, 0, len(b.runtimeModuleRegistrars))
116		for i, registrar := range b.runtimeModuleRegistrars {
117			if registrar == nil {
118				return nil, fmt.Errorf("runtime module registrar at index %d is nil", i)
119			}
120			runtimeRegistrars = append(runtimeRegistrars, registrar)
121		}
122		inits := make([]RuntimeInitializer, 0, len(b.runtimeInitializers))
123		for i, init := range b.runtimeInitializers {
124			if init == nil {
125				return nil, fmt.Errorf("runtime initializer at index %d is nil", i)
126			}
127			inits = append(inits, init)
128		}
129	
130		if err := validateUniqueIDs(modules_, "module"); err != nil {
131			return nil, err
132		}
133		if err := validateUniqueIDs(runtimeRegistrars, "runtime module registrar"); err != nil {
134			return nil, err
135		}
136		if err := validateUniqueIDs(inits, "runtime initializer"); err != nil {
137			return nil, err
138		}
139	
140		b.built = true
141	
142		return &Factory{
143			settings: builderSettings{
144				requireOptions: append([]require.Option(nil), b.settings.requireOptions...),
145			},
146			modules:                 append([]ModuleSpec(nil), modules_...),
147			runtimeModuleRegistrars: append([]RuntimeModuleRegistrar(nil), runtimeRegistrars...),
148			runtimeInitializers:     append([]RuntimeInitializer(nil), inits...),
149		}, nil
150	}
151	
152	// NewRuntime creates a new owned runtime instance from this factory's frozen
153	// composition plan.
154	func (f *Factory) NewRuntime(ctx context.Context) (*Runtime, error) {
155		if f == nil {
156			return nil, fmt.Errorf("factory is nil")
157		}
158		if ctx == nil {
159			ctx = context.Background()
160		}
161	
162		vm := goja.New()
163		loop := eventloop.NewEventLoop()
164		go loop.Start()
165	
166		owner := runtimeowner.NewRunner(vm, loop, runtimeowner.Options{
167			Name:          "go-go-goja-runtime",
168			RecoverPanics: true,
169		})
170		// #nosec G118 -- the runtime owns this cancel func and calls it on close and on setup failures.
171		runtimeCtx, runtimeCtxCancel := context.WithCancel(context.Background())
172		runtimeValues := map[string]any{}
173	
174		rt := &Runtime{
175			VM:               vm,
176			Loop:             loop,
177			Owner:            owner,
178			Values:           runtimeValues,
179			runtimeCtx:       runtimeCtx,
180			runtimeCtxCancel: runtimeCtxCancel,
181		}
182	
183		runtimebridge.Store(vm, runtimebridge.Bindings{
184			Context: runtimeCtx,
185			Loop:    loop,
186			Owner:   owner,
187		})
188	
189		reg := require.NewRegistry(f.settings.requireOptions...)
190		for _, mod := range f.modules {
191			if err := mod.Register(reg); err != nil {
192				_ = rt.Close(ctx)
193				return nil, fmt.Errorf("register module %q: %w", mod.ID(), err)
194			}
195		}
196		moduleCtx := &RuntimeModuleContext{
197			Context:   runtimeCtx,
198			VM:        vm,
199			Loop:      loop,
200			Owner:     owner,
201			AddCloser: rt.AddCloser,
202			Values:    runtimeValues,
203		}
204		for _, registrar := range f.runtimeModuleRegistrars {
205			if err := registrar.RegisterRuntimeModules(moduleCtx, reg); err != nil {
206				_ = rt.Close(ctx)
207				return nil, fmt.Errorf("runtime module registrar %q: %w", registrar.ID(), err)
208			}
209		}
210	
211		reqMod := reg.Enable(vm)
212		console.Enable(vm)
213		rt.Require = reqMod
214	
215		initCtx := &RuntimeContext{
216			Context: runtimeCtx,
217			VM:      vm,
218			Require: reqMod,
219			Loop:    loop,
220			Owner:   owner,
221			Values:  rt.Values,
222		}
223		for _, init := range f.runtimeInitializers {
224			if err := init.InitRuntime(initCtx); err != nil {
225				_ = rt.Close(ctx)
226				return nil, fmt.Errorf("runtime initializer %q: %w", init.ID(), err)
227			}
228		}
229	
230		return rt, nil
231	}

