    44	// InvokeInRuntime invokes a verb inside an already-live caller-owned runtime.
    45	// Unlike the default Commands()/invoke() path, it does not create or close the runtime.
    46	func (r *Registry) InvokeInRuntime(ctx context.Context, runtime *engine.Runtime, verb *VerbSpec, parsedValues *values.Values) (interface{}, error) {
    47		if r == nil {
    48			return nil, fmt.Errorf("registry is nil")
    49		}
    50		if runtime == nil {
    51			return nil, fmt.Errorf("runtime is nil")
    52		}
    53		if verb == nil {
    54			return nil, fmt.Errorf("verb is nil")
    55		}
    56		plan, err := buildVerbBindingPlan(r, verb)
    57		if err != nil {
    58			return nil, err
    59		}
    60		args, err := buildArguments(parsedValues, plan, r.RootDir)
    61		if err != nil {
    62			return nil, err
    63		}
    64	
    65		ret, err := runtime.Owner.Call(ctx, "jsverbs.invoke", func(_ context.Context, vm *goja.Runtime) (interface{}, error) {
    66			if _, err := runtime.Require.Require(verb.File.ModulePath); err != nil {
    67				return nil, err
    68			}
    69			registryValue := vm.Get("__glazedVerbRegistry")
    70			if registryValue == nil || goja.IsUndefined(registryValue) || goja.IsNull(registryValue) {
    71				return nil, fmt.Errorf("js verb registry not initialized")
    72			}
    73			registryObject := registryValue.ToObject(vm)
    74			entryValue := registryObject.Get(verb.File.ModulePath)
    75			if entryValue == nil || goja.IsUndefined(entryValue) || goja.IsNull(entryValue) {
    76				return nil, fmt.Errorf("js verb module entry missing for %s", verb.File.ModulePath)
    77			}
    78			entryObject := entryValue.ToObject(vm)
    79			fnValue := entryObject.Get(verb.FunctionName)
    80			fn, ok := goja.AssertFunction(fnValue)
    81			if !ok {
    82				return nil, fmt.Errorf("js function %s not captured for %s", verb.FunctionName, verb.File.RelPath)
    83			}
    84			jsArgs := make([]goja.Value, 0, len(args))
    85			for _, arg := range args {
    86				jsArgs = append(jsArgs, vm.ToValue(arg))
    87			}
    88			result, err := fn(goja.Undefined(), jsArgs...)
    89			if err != nil {
    90				return nil, err
    91			}
    92			if result == nil || goja.IsUndefined(result) || goja.IsNull(result) {
    93				return nil, nil
    94			}
    95			if promise, ok := result.Export().(*goja.Promise); ok {
    96				return promise, nil
    97			}
    98			return result.Export(), nil
    99		})
   100		if err != nil {
   101			return nil, err
   102		}
   103	
   104		if promise, ok := ret.(*goja.Promise); ok {
   105			return waitForPromise(ctx, runtime, promise)
   106		}
   107		return ret, nil
   108	}
   109	
   110	func buildArguments(parsedValues *values.Values, plan *VerbBindingPlan, rootDir string) ([]interface{}, error) {
   111		sectionValues := map[string]map[string]interface{}{}
   112		if parsedValues == nil {
   113			parsedValues = values.New()
   114		}
   115		allValues := parsedValues.GetDataMap()
   116	
   117		parsedValues.ForEach(func(slug string, value *values.SectionValues) {
   118			sectionMap := map[string]interface{}{}
   119			value.Fields.ForEach(func(_ string, fieldValue *fields.FieldValue) {
   120				if fieldValue == nil || fieldValue.Definition == nil {
   121					return
   122				}
   123				sectionMap[fieldValue.Definition.Name] = fieldValue.Value
   124			})
   125			sectionValues[slug] = sectionMap
   126		})
   127	
   128		args := make([]interface{}, 0, len(plan.Parameters))
   129		for _, binding := range plan.Parameters {
   130			switch binding.Mode {
   131			case BindingModeAll:
   132				args = append(args, allValues)
   133				continue
   134			case BindingModeContext:
   135				args = append(args, map[string]interface{}{
   136					"verb":       plan.Verb.FullPath(),
   137					"function":   plan.Verb.FunctionName,
   138					"module":     plan.Verb.File.ModulePath,
   139					"sourceFile": fileSourcePath(plan.Verb.File),
   140					"rootDir":    rootDir,
   141					"values":     allValues,
   142					"sections":   sectionValues,
   143				})
   144				continue
   145			case BindingModeSection:
   146				args = append(args, cloneMap(sectionValues[binding.SectionSlug]))
   147				continue
   148			case BindingModePositional:
   149				value := sectionValues[binding.SectionSlug][binding.Field.Name]
   150				if binding.Param.Rest {
   151					rv := reflect.ValueOf(value)
   152					if rv.IsValid() && (rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array) {
   153						for i := 0; i < rv.Len(); i++ {
   154							args = append(args, rv.Index(i).Interface())
   155						}
   156						continue
   157					}
   158				}
   159				args = append(args, value)
   160			default:
   161				return nil, fmt.Errorf("%s parameter %q has unsupported binding mode %q", plan.Verb.SourceRef(), binding.Param.Name, binding.Mode)
   162			}
   163		}
   164		return args, nil
   165	}
   166	
   167	func (r *Registry) sourceLoader(modulePath string) ([]byte, error) {
   168		file := r.filesByModule[modulePath]
   169		if file == nil {
   170			return nil, require.ModuleFileDoesNotExistError
   171		}
   172		return []byte(r.injectOverlay(modulePath, file, string(file.Source))), nil
   173	}
   174	
   175	func (r *Registry) injectOverlay(moduleKey string, file *FileSpec, source string) string {
   176		functionNames := []string{}
   177		if file != nil {
   178			for _, fn := range file.Functions {
   179				functionNames = append(functionNames, fn.Name)
   180			}
   181			sort.Strings(functionNames)
   182		}
   183	
   184		var suffix strings.Builder
   185		suffix.WriteString("\n")
   186		suffix.WriteString(`globalThis.__glazedVerbRegistry = globalThis.__glazedVerbRegistry || {};` + "\n")
   187		suffix.WriteString(`globalThis.__glazedVerbRegistry["`)
   188		suffix.WriteString(moduleKey)
   189		suffix.WriteString(`"] = {`)
   190		for i, name := range functionNames {
   191			if i > 0 {
