   102	func (r *Registry) buildDescription(verb *VerbSpec) (*cmds.CommandDescription, error) {
   103		plan, err := buildVerbBindingPlan(r, verb)
   104		if err != nil {
   105			return nil, err
   106		}
   107	
   108		sections := map[string]*schema.SectionImpl{}
   109		ordered := []string{}
   110	
   111		ensureSection := func(slug, title, description string) (*schema.SectionImpl, error) {
   112			slug = strings.TrimSpace(slug)
   113			if slug == "" {
   114				slug = schema.DefaultSlug
   115			}
   116			if section, ok := sections[slug]; ok {
   117				if section.Name == "" && title != "" {
   118					section.Name = title
   119				}
   120				if section.Description == "" && description != "" {
   121					section.Description = description
   122				}
   123				return section, nil
   124			}
   125			if title == "" {
   126				if slug == schema.DefaultSlug {
   127					title = "Arguments"
   128				} else {
   129					title = prettySectionTitle(slug)
   130				}
   131			}
   132			section, err := schema.NewSection(slug, title, schema.WithDescription(description))
   133			if err != nil {
   134				return nil, err
   135			}
   136			sections[slug] = section
   137			ordered = append(ordered, slug)
   138			return section, nil
   139		}
   140	
   141		if _, err := ensureSection(schema.DefaultSlug, "Arguments", ""); err != nil {
   142			return nil, err
   143		}
   144	
   145		for _, slug := range plan.ReferencedSections {
   146			spec, ok := r.ResolveSection(verb, slug)
   147			if !ok {
   148				return nil, fmt.Errorf("%s references unknown section %q", verb.SourceRef(), slug)
   149			}
   150			section, err := ensureSection(spec.Slug, spec.Title, spec.Description)
   151			if err != nil {
   152				return nil, err
   153			}
   154			fieldNames := make([]string, 0, len(spec.Fields))
   155			for name := range spec.Fields {
   156				fieldNames = append(fieldNames, name)
   157			}
   158			sort.Strings(fieldNames)
   159			for _, name := range fieldNames {
   160				field, err := buildFieldDefinition(spec.Fields[name])
   161				if err != nil {
   162					return nil, fmt.Errorf("%s section %s field %s: %w", verb.SourceRef(), slug, name, err)
   163				}
   164				section.AddFields(field)
   165			}
   166		}
   167	
   168		addField := func(sectionSlug string, fieldSpec *FieldSpec) error {
   169			section, err := ensureSection(sectionSlug, "", "")
   170			if err != nil {
   171				return err
   172			}
   173			field, err := buildFieldDefinition(fieldSpec)
   174			if err != nil {
   175				return err
   176			}
   177			if field.IsArgument && sectionSlug != schema.DefaultSlug {
   178				return fmt.Errorf("arguments are only supported in the default section (field %s in %s)", field.Name, sectionSlug)
   179			}
   180			section.AddFields(field)
   181			return nil
   182		}
   183	
   184		for _, binding := range plan.Parameters {
   185			if binding.Mode != BindingModePositional {
   186				continue
   187			}
   188			if err := addField(binding.SectionSlug, binding.Field); err != nil {
   189				return nil, fmt.Errorf("%s field %s: %w", verb.SourceRef(), binding.Param.Name, err)
   190			}
   191		}
   192	
   193		for _, extraField := range plan.ExtraFields {
   194			if err := addField(extraField.SectionSlug, extraField.Field); err != nil {
   195				return nil, fmt.Errorf("%s field %s: %w", verb.SourceRef(), extraField.Name, err)
   196			}
   197		}
   198	
   199		description := cmds.NewCommandDescription(
   200			verb.Name,
   201			cmds.WithShort(verb.Short),
   202			cmds.WithLong(verb.Long),
   203			cmds.WithParents(verb.Parents...),
   204			cmds.WithSource("jsverbs:"+verb.SourceRef()),
   205		)
   206		for _, slug := range ordered {
   207			description.Schema.Set(slug, sections[slug])
   208		}
   209		return description, nil
   210	}
