 11	type BindingMode string
 12	
 13	const (
 14		BindingModePositional BindingMode = "positional"
 15		BindingModeSection    BindingMode = "section"
 16		BindingModeAll        BindingMode = "all"
 17		BindingModeContext    BindingMode = "context"
 18	)
