 40	func buildVerbBindingPlan(r *Registry, verb *VerbSpec) (*VerbBindingPlan, error) {
 41		if r == nil {
 42			return nil, fmt.Errorf("registry is nil")
 43		}
 44	
 45		referencedSections := map[string]struct{}{}
 46		for _, slug := range verb.UseSections {
 47			referencedSections[slug] = struct{}{}
 48		}
 49		for _, fieldMeta := range verb.Fields {
 50			if fieldMeta == nil {
 51				continue
 52			}
 53			if fieldMeta.Section != "" {
 54				referencedSections[fieldMeta.Section] = struct{}{}
 55			}
 56			switch bind := normalizeBind(fieldMeta.Bind); bind {
 57			case "", "all", "context":
 58			default:
 59				referencedSections[bind] = struct{}{}
 60			}
 61		}
 62	
 63		plan := &VerbBindingPlan{
 64			Verb:       verb,
 65			Parameters: make([]ParameterBinding, 0, len(verb.Params)),
 66		}
 67	
 68		usedFields := map[string]struct{}{}
 69		for _, param := range verb.Params {
 70			fieldSpec := verb.Field(param.Name)
 71			if fieldSpec != nil {
 72				usedFields[param.Name] = struct{}{}
 73				fieldSpec = fieldSpec.Clone()
 74			} else {
 75				fieldSpec = inferFieldFromParam(param)
 76			}
 77			if fieldSpec == nil {
 78				continue
 79			}
 80			if fieldSpec.Name == "" {
 81				fieldSpec.Name = param.Name
 82			}
 83			binding, err := resolveParameterBinding(verb, param, fieldSpec)
 84			if err != nil {
 85				return nil, err
 86			}
 87			plan.Parameters = append(plan.Parameters, binding)
 88		}
 89	
 90		extraFieldNames := make([]string, 0, len(verb.Fields))
 91		for name := range verb.Fields {
 92			if _, ok := usedFields[name]; ok {
 93				continue
 94			}
 95			extraFieldNames = append(extraFieldNames, name)
 96		}
 97		sort.Strings(extraFieldNames)
 98		for _, name := range extraFieldNames {
 99			fieldSpec := verb.Fields[name]
100			if fieldSpec == nil {
101				continue
102			}
103			fieldSpec = fieldSpec.Clone()
104			if fieldSpec.Name == "" {
105				fieldSpec.Name = name
106			}
107			if normalizeBind(fieldSpec.Bind) != "" {
108				continue
109			}
110			sectionSlug := schema.DefaultSlug
111			if fieldSpec.Section != "" {
112				sectionSlug = fieldSpec.Section
113			}
114			plan.ExtraFields = append(plan.ExtraFields, ExtraFieldBinding{
115				Name:        name,
116				Field:       fieldSpec,
117				SectionSlug: sectionSlug,
118			})
119		}
120	
121		for slug := range referencedSections {
122			if _, ok := r.ResolveSection(verb, slug); !ok {
123				return nil, fmt.Errorf("%s references unknown section %q", verb.SourceRef(), slug)
124			}
125		}
126	
127		plan.ReferencedSections = make([]string, 0, len(referencedSections))
128		seenSections := map[string]struct{}{}
129		appendSection := func(slug string) {
130			if _, ok := referencedSections[slug]; !ok {
131				return
132			}
133			if _, ok := seenSections[slug]; ok {
134				return
135			}
136			plan.ReferencedSections = append(plan.ReferencedSections, slug)
137			seenSections[slug] = struct{}{}
138		}
139	
140		for _, slug := range verb.File.SectionOrder {
141			appendSection(slug)
142		}
143		for _, slug := range r.SharedSectionOrder {
144			appendSection(slug)
145		}
146	
147		remaining := make([]string, 0, len(referencedSections))
148		for slug := range referencedSections {
149			if _, ok := seenSections[slug]; ok {
150				continue
151			}
152			remaining = append(remaining, slug)
153		}
154		sort.Strings(remaining)
155		for _, slug := range remaining {
156			appendSection(slug)
157		}
158	
159		return plan, nil
160	}
161	
162	func resolveParameterBinding(verb *VerbSpec, param ParameterSpec, fieldSpec *FieldSpec) (ParameterBinding, error) {
163		binding := ParameterBinding{
164			Param:       param,
165			Field:       fieldSpec,
166			Mode:        BindingModePositional,
167			SectionSlug: schema.DefaultSlug,
168		}
169		switch bind := normalizeBind(fieldSpec.Bind); bind {
170		case "":
171			if param.Kind != ParameterIdentifier && param.Kind != ParameterUnknown {
172				return ParameterBinding{}, fmt.Errorf("%s parameter %q requires a bind because it is %s", verb.SourceRef(), param.Name, param.Kind)
173			}
174			if fieldSpec.Section != "" {
175				binding.SectionSlug = fieldSpec.Section
176			}
177		case "all":
178			binding.Mode = BindingModeAll
179			binding.SectionSlug = ""
180		case "context":
181			binding.Mode = BindingModeContext
182			binding.SectionSlug = ""
183		default:
184			binding.Mode = BindingModeSection
185			binding.SectionSlug = bind
186		}
187		return binding, nil
188	}
189	
190	func normalizeBind(bind string) string {
191		switch cleaned := strings.TrimSpace(bind); cleaned {
192		case "":
193			return ""
194		case "all", "context":
195			return cleaned
196		default:
197			return cleanCommandWord(cleaned)
198		}
199	}

