 56	// NativeModuleSpec registers a single native module loader.
 57	type NativeModuleSpec struct {
 58		ModuleID   string
 59		ModuleName string
 60		Loader     require.ModuleLoader
 61	}
 62	
 63	func (s NativeModuleSpec) ID() string {
 64		if strings.TrimSpace(s.ModuleID) != "" {
 65			return strings.TrimSpace(s.ModuleID)
 66		}
 67		return "native:" + strings.TrimSpace(s.ModuleName)
 68	}
 69	
 70	func (s NativeModuleSpec) Register(reg *require.Registry) error {
 71		if reg == nil {
 72			return fmt.Errorf("require registry is nil")
 73		}
 74		name := strings.TrimSpace(s.ModuleName)
 75		if name == "" {
 76			return fmt.Errorf("module name is empty")
 77		}
 78		if s.Loader == nil {
 79			return fmt.Errorf("native module %q loader is nil", name)
 80		}
 81		reg.RegisterNativeModule(name, s.Loader)
 82		return nil
 83	}
