299	func buildInputItemsFromTurn(t *turns.Turn) []responsesInput {
300		var items []responsesInput
301		if t == nil {
302			return items
303		}
304		roleFor := func(kind turns.BlockKind) string {
305			switch kind {
306			case turns.BlockKindSystem:
307				return "system"
308			case turns.BlockKindUser:
309				return "user"
310			case turns.BlockKindToolUse:
311				return "tool"
312			case turns.BlockKindLLMText, turns.BlockKindToolCall, turns.BlockKindReasoning, turns.BlockKindOther:
313				return "assistant"
314			}
315			return "assistant"
316		}
317	
318		// Helpers
319		appendMessage := func(b turns.Block) {
320			role := roleFor(b.Kind)
321			var parts []responsesContentPart
322			if v, ok := b.Payload[turns.PayloadKeyText]; ok && v != nil {
323				if s, ok := v.(string); ok && strings.TrimSpace(s) != "" {
324					ctype := "input_text"
325					if role == "assistant" {
326						ctype = "output_text"
327					}
328					parts = append(parts, responsesContentPart{Type: ctype, Text: s})
329				}
330			}
331			if len(parts) > 0 {
332				items = append(items, responsesInput{Role: role, Content: parts})
333			}
334		}
335		appendFunctionCall := func(b turns.Block) {
336			name, _ := b.Payload[turns.PayloadKeyName].(string)
337			callID, _ := b.Payload[turns.PayloadKeyID].(string)
338			itemID, _ := b.Payload[turns.PayloadKeyItemID].(string)
339			args := b.Payload[turns.PayloadKeyArgs]
340			var argsJSON string
341			if args != nil {
342				if s, ok := args.(string); ok {
343					argsJSON = s
344				} else if bb, err := json.Marshal(args); err == nil {
345					argsJSON = string(bb)
346				}
347			}
348			if callID != "" && name != "" {
349				ri := responsesInput{Type: "function_call", CallID: callID, Name: name, Arguments: argsJSON}
350				if itemID != "" {
351					ri.ID = itemID
352				}
353				items = append(items, ri)
354			}
355		}
356		appendFunctionCallOutput := func(b turns.Block) {
357			toolID, _ := b.Payload[turns.PayloadKeyID].(string)
358			resultJSON := toolUsePayloadToJSONString(b.Payload)
359			if toolID != "" {
360				// Responses expects call_id on function_call_output
361				items = append(items, responsesInput{Type: "function_call_output", CallID: toolID, Output: resultJSON})
362			}
363		}
364	
365		reasoningItem := func(b turns.Block) responsesInput {
366			enc, _ := b.Payload[turns.PayloadKeyEncryptedContent].(string)
367			summary := reasoningSummaryEntriesFromPayload(b.Payload)
368			if summary == nil {
369				summary = make([]any, 0)
370			}
371			ri := responsesInput{Type: "reasoning", ID: b.ID, Summary: &summary}
372			if enc != "" {
373				ri.EncryptedContent = enc
374			}
375			return ri
376		}
377	
378		// Process blocks in-order so every function_call can retain its required reasoning predecessor.
379		for i := 0; i < len(t.Blocks); i++ {
380			b := t.Blocks[i]
381			switch b.Kind {
382			case turns.BlockKindReasoning:
383				nextIdx := i + 1
384				if nextIdx >= len(t.Blocks) {
385					continue
386				}
387				next := t.Blocks[nextIdx]
