397								ID:      msgID,
398								Content: []responsesContentPart{{Type: "output_text", Text: s}},
399							})
400							i = nextIdx
401							continue
402						}
403					}
404				case turns.BlockKindToolCall:
405					items = append(items, reasoningItem(b))
406					j := nextIdx
407					for j < len(t.Blocks) {
408						nb := t.Blocks[j]
409						if nb.Kind == turns.BlockKindToolCall {
